import { useState } from 'react';
import { JxButton, JxCalendar } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date) => void;
}

function startOfDay(date: Date): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

function addDays(date: Date, days: number): Date {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [selected, setSelected] = useState<Date>(() => startOfDay(new Date()));

  const handleSelect = (date: Date) => {
    const normalized = startOfDay(date);
    setSelected(normalized);
    onChange?.(normalized);
  };

  const quickOptions = [
    { label: 'Сегодня', getValue: () => startOfDay(new Date()) },
    { label: 'Вчера', getValue: () => addDays(startOfDay(new Date()), -1) },
    { label: 'Неделя назад', getValue: () => addDays(startOfDay(new Date()), -7) },
  ];

  return (
    <div className="jx-stack jx-stack-gap-md">
      <div className="jx-inline jx-inline-gap-sm">
        {quickOptions.map((option) => (
          <JxButton
            key={option.label}
            variant="secondary"
            size="sm"
            onClick={() => handleSelect(option.getValue())}
          >
            {option.label}
          </JxButton>
        ))}
      </div>
      <JxCalendar
        value={selected}
        onValueChange={handleSelect}
      />
    </div>
  );
}

